    private Optional<ConsumerGroupMetadata> initializeGroupMetadata(final ConsumerConfig config,
                                                                    final GroupRebalanceConfig groupRebalanceConfig) {
        final Optional<ConsumerGroupMetadata> groupMetadata = initializeGroupMetadata(
            groupRebalanceConfig.groupId,
            groupRebalanceConfig.groupInstanceId
        );
        if (groupMetadata.isEmpty()) {
            config.ignore(ConsumerConfig.AUTO_COMMIT_INTERVAL_MS_CONFIG);
            config.ignore(THROW_ON_FETCH_STABLE_OFFSET_UNSUPPORTED);
        }
        return groupMetadata;
    }

    private Optional<ConsumerGroupMetadata> initializeGroupMetadata(final String groupId,
                                                                    final Optional<String> groupInstanceId) {
        if (groupId != null) {
            if (groupId.isEmpty()) {
                throw new InvalidGroupIdException("The configured " + ConsumerConfig.GROUP_ID_CONFIG
                    + " should not be an empty string or whitespace.");
            } else {
                return Optional.of(initializeConsumerGroupMetadata(groupId, groupInstanceId));
            }
        }
        return Optional.empty();
    }

    @SuppressWarnings("removal")
    private ConsumerGroupMetadata initializeConsumerGroupMetadata(final String groupId,
                                                                  final Optional<String> groupInstanceId) {
        return new ConsumerGroupMetadata(
            groupId,
            JoinGroupRequest.UNKNOWN_GENERATION_ID,
            JoinGroupRequest.UNKNOWN_MEMBER_ID,
            groupInstanceId
        );
    }

    @SuppressWarnings("removal")
    private void updateGroupMetadata(final Optional<Integer> memberEpoch, final String memberId) {
        memberEpoch.ifPresent(epoch -> groupMetadata.updateAndGet(
                oldGroupMetadataOptional -> oldGroupMetadataOptional.map(
                    oldGroupMetadata -> new ConsumerGroupMetadata(
                        oldGroupMetadata.groupId(),
                        memberEpoch.orElse(oldGroupMetadata.generationId()),
                        memberId,
                        oldGroupMetadata.groupInstanceId()
                    )
                )
            )
        );
    }

    void setGroupAssignmentSnapshot(final Set<TopicPartition> partitions) {
        groupAssignmentSnapshot.set(Collections.unmodifiableSet(partitions));
    }

    void setHasPendingReconciliation(final boolean hasPendingReconciliation) {
        this.hasPendingReconciliation = hasPendingReconciliation;
    }

    @Override
    public void registerMetricForSubscription(KafkaMetric metric) {
        if (!metrics().containsKey(metric.metricName())) {
            clientTelemetryReporter.ifPresent(reporter -> reporter.metricChange(metric));
        } else {
            log.debug("Skipping registration for metric {}. Existing consumer metrics cannot be overwritten.", metric.metricName());
        }
    }

    @Override
    public void unregisterMetricFromSubscription(KafkaMetric metric) {
        if (!metrics().containsKey(metric.metricName())) {
            clientTelemetryReporter.ifPresent(reporter -> reporter.metricRemoval(metric));
        } else {
            log.debug("Skipping unregistration for metric {}. Existing consumer metrics cannot be removed.", metric.metricName());
        }
    }

    /**
     * poll implementation using {@link ApplicationEventHandler}.
     *  1. Poll for background events. If there's a fetch response event, process the record and return it. If it is
     *  another type of event, process it.
     *  2. Send fetches if needed.
     *  If the timeout expires, return an empty ConsumerRecord.
     *
     * @param timeout timeout of the poll loop
     * @return ConsumerRecord.  It can be empty if time timeout expires.
     *
     * @throws org.apache.kafka.common.errors.WakeupException if {@link #wakeup()} is called before or while this
     *             function is called
     * @throws org.apache.kafka.common.errors.InterruptException if the calling thread is interrupted before or while
     *             this function is called
     * @throws org.apache.kafka.common.errors.RecordTooLargeException if the fetched record is larger than the maximum
     *             allowable size
     * @throws org.apache.kafka.common.KafkaException for any other unrecoverable errors
     * @throws java.lang.IllegalStateException if the consumer is not subscribed to any topics or manually assigned any
     *             partitions to consume from or an unexpected error occurred
     * @throws org.apache.kafka.clients.consumer.OffsetOutOfRangeException if the fetch position of the consumer is
     *             out of range and no offset reset policy is configured.
     * @throws org.apache.kafka.common.errors.TopicAuthorizationException if the consumer is not authorized to read
     *             from a partition
     * @throws org.apache.kafka.common.errors.SerializationException if the fetched records cannot be deserialized
     * @throws org.apache.kafka.common.errors.UnsupportedAssignorException if the `group.remote.assignor` configuration
     *             is set to an assignor that is not available on the broker.
     */
    @Override
    public ConsumerRecords<K, V> poll(final Duration timeout) {
        Timer timer = time.timer(timeout);

        acquireAndEnsureOpen();
        try {
            kafkaConsumerMetrics.recordPollStart(timer.currentTimeMs());

            if (subscriptions.hasNoSubscriptionOrUserAssignment()) {
                throw new IllegalStateException("Consumer is not subscribed to any topics or assigned any partitions");
            }

            // This distinguishes the first pass of the inner do/while loop from subsequent passes for the
            // inflight poll event logic.
            boolean firstPass = true;

            do {
                // We must not allow wake-ups between polling for fetches and returning the records.
                // If the polled fetches are not empty the consumed position has already been updated in the polling
                // of the fetches. A wakeup between returned fetches and returning records would lead to never
                // returning the records in the fetches. Thus, we trigger a possible wake-up before we poll fetches.
                wakeupTrigger.maybeTriggerWakeup();

                checkInflightPoll(timer, firstPass);
                firstPass = false;
                final Fetch<K, V> fetch = pollForFetches(timer);
                if (!fetch.isEmpty()) {
                    // before returning the fetched records, we can send off the next round of fetches
                    // and avoid block waiting for their responses to enable pipelining while the user
                    // is handling the fetched records.
                    //
                    // NOTE: since the consumed position has already been updated, we must not allow
                    // wakeups or any other errors to be triggered prior to returning the fetched records.
                    sendPrefetches(timer);

                    if (fetch.records().isEmpty()) {
                        log.trace("Returning empty records from `poll()` "
                            + "since the consumer's position has advanced for at least one topic partition");
                    }

                    return interceptors.onConsume(new ConsumerRecords<>(fetch.records(), fetch.nextOffsets()));
                }
                // We will wait for retryBackoffMs
            } while (timer.notExpired());

            return ConsumerRecords.empty();
        } finally {
            kafkaConsumerMetrics.recordPollEnd(timer.currentTimeMs());
            release();
        }
    }

    /**
     * {@code checkInflightPoll()} manages the lifecycle of the {@link AsyncPollEvent}. If no event is
     * currently processing, a new one is started asynchronously. Each invocation checks whether the
     * <em>inflight</em> event has completed; if so, a new event is submitted in its place so a fetch request
     * stays in flight. If the completed event left records buffered no new
     * event is submitted here (it would gate those records behind a fresh validate-positions stage).
     * Instead the buffered records are returned and the next fetch is pipelined by {@link #poll(Duration)} via
     * {@link #sendPrefetches(Timer)}.
     */
    private void checkInflightPoll(Timer timer, boolean firstPass) {
        // Clear the current inflight poll if we can, so a new one (and a new fetch) is submitted below.
        // On the first pass this may clear a leftover from the previous poll(). On later passes it clears
        // inflights that have completed. A completed poll that filled the buffer is kept, so its records
        // are returned first (see maybeClearPreviousInflightPoll).
        if (inflightPoll != null && (firstPass || inflightPoll.isComplete())) {
            maybeClearPreviousInflightPoll();
        }

        boolean newlySubmittedEvent = false;

        if (inflightPoll == null) {
            inflightPoll = new AsyncPollEvent(calculateDeadlineMs(timer), time.milliseconds());
            newlySubmittedEvent = true;
            log.trace("Inflight event {} submitted", inflightPoll);
            applicationEventHandler.add(inflightPoll);
        }

        try {
            // Note: this is calling user-supplied code, so make sure that any errors thrown here are caught and
            // the inflight event is cleared.
            offsetCommitCallbackInvoker.executeCallbacks();
            processBackgroundEvents();
        } catch (Throwable t) {
            // If an exception was thrown during execution of offset commit callbacks or background events,
            // bubble it up to the user but make sure to clear out the inflight request because the error effectively
            // renders it complete.
            log.trace("Inflight event {} failed due to {}, clearing", inflightPoll, String.valueOf(t));
            inflightPoll = null;
            throw ConsumerUtils.maybeWrapAsKafkaException(t);
        } finally {
            timer.update();
        }

        if (inflightPoll != null) {
            maybeClearCurrentInflightPoll(newlySubmittedEvent);
        }
    }

    private void maybeClearPreviousInflightPoll() {
        if (inflightPoll.isComplete()) {
            Optional<KafkaException> errorOpt = inflightPoll.error();

            if (errorOpt.isPresent()) {
                // If the previous inflight event is complete, check if it resulted in an error. If there was
                // an error, throw it without delay.
                KafkaException error = errorOpt.get();
                log.trace("Previous inflight event {} completed with an error ({}), clearing", inflightPoll, error);
                inflightPoll = null;
                throw error;
            } else {
                // Successful case...
                if (fetchBuffer.isEmpty()) {
                    // If it completed without error, but without populating the fetch buffer, clear the event
                    // so that a new event will be enqueued below.
                    log.trace("Previous inflight event {} completed without filling the buffer, clearing", inflightPoll);
                    inflightPoll = null;
                } else {
                    // However, if the event completed, and it populated the buffer, *don't* create a new event.
                    // This is to prevent an edge case of starvation when poll() is called with a timeout of 0.
                    // If a new event was created on *every* poll, each time the event would have to complete the
                    // validate positions stage before the data in the fetch buffer is used. Because there is
                    // no blocking, and effectively a 0 wait, the data in the fetch buffer is continuously ignored
                    // leading to no data ever being returned from poll().
                    log.trace("Previous inflight event {} completed and filled the buffer, not clearing", inflightPoll);
                }
            }
        } else if (inflightPoll.isExpired(time) && inflightPoll.isValidatePositionsComplete()) {
            // The inflight event validated positions, but it has expired.
            log.trace("Previous inflight event {} expired without completing, clearing", inflightPoll);
            inflightPoll = null;
        }
    }

    private void maybeClearCurrentInflightPoll(boolean newlySubmittedEvent) {
        if (inflightPoll.isComplete()) {
            Optional<KafkaException> errorOpt = inflightPoll.error();

            if (errorOpt.isPresent()) {
                // If the inflight event completed with an error, throw it without delay.
                KafkaException error = errorOpt.get();
                log.trace("Inflight event {} completed with an error ({}), clearing", inflightPoll, error);
                inflightPoll = null;
                throw error;
            } else {
                log.trace("Inflight event {} completed without error, clearing", inflightPoll);
                inflightPoll = null;
            }
        } else if (!newlySubmittedEvent) {
            if (inflightPoll.isExpired(time) && inflightPoll.isValidatePositionsComplete()) {
                // The inflight event validated positions, but it has expired.
                log.trace("Inflight event {} expired without completing, clearing", inflightPoll);
                inflightPoll = null;
            }
        }
    }

