    @Override
    public Set<String> subscription() {
        acquireAndEnsureOpen();
        try {
            return Set.copyOf(subscriptions.subscription());
        } finally {
            release();
        }
    }

    @Override
    public void assign(Collection<TopicPartition> partitions) {
        acquireAndEnsureOpen();
        try {
            if (partitions == null) {
                throw new IllegalArgumentException("Topic partitions collection to assign to cannot be null");
            }

            if (partitions.isEmpty()) {
                unsubscribe();
                return;
            }

            for (TopicPartition tp : partitions) {
                String topic = (tp != null) ? tp.topic() : null;
                if (isBlank(topic))
                    throw new IllegalArgumentException("Topic partitions to assign to cannot have null or empty topic");
            }

            // Clear the buffered data which are not a part of newly assigned topics
            final Set<TopicPartition> currentTopicPartitions = new HashSet<>();

            for (TopicPartition tp : subscriptions.assignedPartitions()) {
                if (partitions.contains(tp))
                    currentTopicPartitions.add(tp);
            }

            fetchBuffer.retainAll(currentTopicPartitions);

            // assignment change event will trigger autocommit if it is configured and the group id is specified. This is
            // to make sure offsets of topic partitions the consumer is unsubscribing from are committed since there will
            // be no following rebalance.
            //
            // See the ApplicationEventProcessor.process() method that handles this event for more detail.
            applicationEventHandler.addAndGet(new AssignmentChangeEvent(
                time.milliseconds(),
                defaultApiTimeoutDeadlineMs(),
                partitions
            ));
        } finally {
            release();
        }
    }

    @Override
    public void unsubscribe() {
        acquireAndEnsureOpen();
        try {
            fetchBuffer.retainAll(Collections.emptySet());
            Timer timer = time.timer(defaultApiTimeoutMs);
            UnsubscribeEvent unsubscribeEvent = new UnsubscribeEvent(calculateDeadlineMs(timer));
            applicationEventHandler.add(unsubscribeEvent);
            log.info("Unsubscribing all topics or patterns and assigned partitions {}",
                    subscriptions.assignedPartitions());

            try {
                // If users have fatal error, they will get some exceptions in the background queue.
                // When running unsubscribe, these exceptions should be ignored, or users can't unsubscribe successfully.
                // We also skip processing assignment events (PARTITIONS_ASSIGNED, STREAMS_TASKS_ASSIGNED) because
                // they are not relevant anymore (consumer already unsubscribing).
                processBackgroundEvents(unsubscribeEvent.future(), timer,
                    e -> (e instanceof GroupAuthorizationException || e instanceof TopicAuthorizationException),
                    true);
                log.info("Unsubscribed all topics or patterns and assigned partitions");
            } catch (TimeoutException e) {
                log.error("Failed while waiting for the unsubscribe event to complete");
            }
            resetGroupMetadata();
        } catch (Exception e) {
            log.error("Unsubscribe failed", e);
            throw e;
        } finally {
            release();
        }
    }

    private void resetGroupMetadata() {
        groupMetadata.updateAndGet(
            oldGroupMetadataOptional -> oldGroupMetadataOptional
                .map(oldGroupMetadata -> initializeConsumerGroupMetadata(
                    oldGroupMetadata.groupId(),
                    oldGroupMetadata.groupInstanceId()
                ))
        );
    }

    // Visible for testing
    WakeupTrigger wakeupTrigger() {
        return wakeupTrigger;
    }

    private Fetch<K, V> pollForFetches(Timer timer) {

        // if data is available already, return it immediately
        final Fetch<K, V> fetch = collectFetch();
        if (!fetch.isEmpty()) {
            return fetch;
        }

        long pollTimeout = Math.min(applicationEventHandler.maximumTimeToWait(), timer.remainingMs());

        // Bound the wait when background progress may make fetching possible soon.
        // Use the current application-thread state to avoid relying on stale state from the network thread.
        if (pollTimeout > retryBackoffMs) {
            if (subscriptions.numAssignedPartitions() == 0) {
                // If there are no assigned partitions, reduce the fetch buffer wait time. This may happen when
                // group membership has not been established yet, assignments have been revoked but not reassigned,
                // bootstrap DNS resolution is still in progress, or manual assignment has not happened yet.
                pollTimeout = retryBackoffMs;
            } else if (!subscriptions.hasAllFetchPositions()) {
                // If some partitions do not have valid positions, the background thread may still be resolving them,
                // for example by fetching committed offsets, looking up offsets by timestamp, or backing off after a
                // failure. Reduce the wait time so the application thread can consume data promptly once positions are
                // resolved.
                pollTimeout = retryBackoffMs;
            } else {
                Set<TopicPartition> buffered = fetchBuffer.bufferedPartitions();
                if (subscriptions.hasFetchablePartitions(tp -> !buffered.contains(tp))) {
                    // If any fetchable partition has no buffered data, it may have been skipped due to reconnect
                    // backoff, an in-flight request, or a missing leader. Bound the wait so the application thread
                    // can retry once the condition clears.
                    pollTimeout = retryBackoffMs;
                }
            }
        }

        log.trace("Polling for fetches with timeout {}", pollTimeout);

        Timer pollTimer = time.timer(pollTimeout);
        wakeupTrigger.setFetchAction(fetchBuffer);

        // Wait a bit for some fetched data to arrive, as there may not be anything immediately available. Note the
        // use of a shorter, dedicated "pollTimer" here which updates "timer" so that calling method (poll) will
        // correctly handle the overall timeout.
        try {
            fetchBuffer.awaitWakeup(pollTimer);
        } catch (InterruptException e) {
            log.trace("Interrupt during fetch", e);
            throw e;
        } finally {
            timer.update(pollTimer.currentTimeMs());
            wakeupTrigger.clearTask();
        }

        return collectFetch();
    }

    /**
     * Perform the "{@link FetchCollector#collectFetch(FetchBuffer) fetch collection}" step by reading raw data out
     * of the {@link #fetchBuffer}, converting it to a well-formed {@link CompletedFetch}, validating that it and
     * the internal {@link ConsumerSubscriptionState state} are correct, and then converting it all into a {@link Fetch}
     * for returning.
     */
    private Fetch<K, V> collectFetch() {
        // Do not return buffered records if the background hasn't checked for pending reconciliations
        // for the inflight poll event.
        // This is key because partitions may need revocation, so we need to wait for the reconciliation check
        // that triggers commits and marks partitions as pending revocation, before we can
        // safely collect records from the buffer.
        if (hasPendingReconciliation && inflightPoll != null && !inflightPoll.isReconciliationCheckComplete()) {
            // If the background hasn't had the time to check for pending reconciliation,
            // we need to wait for that check before moving on (instead of returning empty right away,
            // which will lead to blocking on buffer data)
            long timeoutMs = inflightPoll.deadlineMs() - time.milliseconds();
            if (timeoutMs > 0) {
                try {
                    wakeupTrigger.setActiveTask(inflightPoll.reconciliationCheckFuture());
                    ConsumerUtils.getResult(inflightPoll.reconciliationCheckFuture(), timeoutMs);
                } catch (TimeoutException e) {
                    return Fetch.empty();
                } finally {
                    wakeupTrigger.clearTask();
                }
            } else {
                // No time to wait and reconciliation check not complete
                return Fetch.empty();
            }
        }

        // With the non-blocking async poll, it's critical that the application thread wait until the background
        // thread has completed the stage of validating positions. This prevents a race condition where both
        // threads may attempt to update the ConsumerSubscriptionState.position() for a given partition. So if the background
        // thread has not completed that stage for the inflight event, don't attempt to collect data from the fetch
        // buffer. If the inflight event was nulled out by checkInflightPoll(), that implies that it is safe to
        // attempt to collect data from the fetch buffer.
        if (positionsValidator.canSkipUpdateFetchPositions()) {
            return fetchCollector.collectFetch(fetchBuffer);
        }

        if (inflightPoll != null && !inflightPoll.isValidatePositionsComplete()) {
            return Fetch.empty();
        }

        return fetchCollector.collectFetch(fetchBuffer);
    }

    /**
     * Set the fetch position to the committed position (if there is one)
     * or reset it using the offset reset policy the user has configured.
     *
     * @return true iff the operation completed without timing out
     * @throws AuthenticationException       If authentication fails. See the exception for more details
     * @throws NoOffsetForPartitionException If no offset is stored for a given partition and no offset reset policy is
     *                                       defined
     */
    private boolean updateFetchPositions(final Timer timer) {
        try {
            CheckAndUpdatePositionsEvent checkAndUpdatePositionsEvent = new CheckAndUpdatePositionsEvent(calculateDeadlineMs(timer));
            wakeupTrigger.setActiveTask(checkAndUpdatePositionsEvent.future());
            applicationEventHandler.addAndGet(checkAndUpdatePositionsEvent);
        } catch (TimeoutException e) {
            return false;
        } finally {
            wakeupTrigger.clearTask();
        }
        return true;
    }

    /**
     * This method signals the background thread to {@link CreateFetchRequestsEvent create fetch requests} for the
     * pre-fetch case, i.e. right before {@link #poll(Duration)} exits. In the pre-fetch case, the application thread
     * will not wait for confirmation of the request creation before continuing.
     *
     * <p/>
     *
     * At the point this method is called, {@link KafkaConsumer#poll(Duration)} has data ready to return to the user,
     * which means the consumed position was already updated. In order to prevent potential gaps in records, this
     * method is designed to suppress all exceptions.
     *
     * @param timer Provides an upper bound for the event and its {@link CompletableFuture future}
     */
    private void sendPrefetches(Timer timer) {
        try {
            applicationEventHandler.add(new CreateFetchRequestsEvent(calculateDeadlineMs(timer)));
        } catch (Throwable t) {
            // Any unexpected errors will be logged for troubleshooting, but not thrown.
            log.warn("An unexpected error occurred while pre-fetching data in Consumer.poll(), but was suppressed", t);
        }
    }

    @Override
    public boolean updateAssignmentMetadataIfNeeded(Timer timer) {
        offsetCommitCallbackInvoker.executeCallbacks();
        if (subscriptions.hasPatternSubscription()) {
            try {
                applicationEventHandler.addAndGet(new UpdatePatternSubscriptionEvent(calculateDeadlineMs(timer)));
            } catch (TimeoutException e) {
                return false;
            } finally {
                timer.update();
            }
        }
        processBackgroundEvents();

        return updateFetchPositions(timer);
    }

