package org.apache.kafka.connect.runtime.errors;

import java.util.Locale;

/**
 * The different levels of error tolerance.
 */
public enum ToleranceType {

    /**
     * Tolerate no errors.
     */
    NONE,

    /**
     * Tolerate all errors.
     */
    ALL;

    public String value() {
        return name().toLowerCase(Locale.ROOT);
    }

}

