                        || TopicBasedRemoteLogMetadataManagerConfig.REMOTE_LOG_METADATA_TOPIC_NAME.equals(topic)
                        || Topic.CLUSTER_METADATA_TOPIC_NAME.equals(topic)) &&
                config.remoteStorageEnable();
