        boolean has(OptionSpec<?> builder) {
            return options.has(builder);
        }

        <A> Optional<A> valueAsOption(OptionSpec<A> option) {
            return has(option) ? Optional.of(options.valueOf(option)) : Optional.empty();
        }

        boolean hasCreateOption() {
